html,body{margin:0;height:100%;overflow:hidden;background:#07031a;font-family:-apple-system,"SF Pro Display",Inter,system-ui,sans-serif;color:#f4eefc;user-select:none;-webkit-user-select:none;outline:none;touch-action:none}
canvas{position:absolute;inset:0;width:100%;height:100%;display:block}
#slow{position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 50%,rgba(40,120,255,0) 30%,rgba(40,110,255,.45));opacity:0;transition:opacity .5s;mix-blend-mode:screen}
#flash{position:absolute;inset:0;pointer-events:none;background:#fff;opacity:0;mix-blend-mode:overlay}
body::after{content:"";position:absolute;inset:0;pointer-events:none;z-index:4;background:radial-gradient(ellipse at 50% 55%,transparent 55%,rgba(4,1,14,.55)),repeating-linear-gradient(0deg,rgba(255,255,255,.018) 0 1px,transparent 1px 3px)}
#fever{position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .4s;mix-blend-mode:screen;background:linear-gradient(120deg,rgba(255,60,200,.35),rgba(60,255,255,.3),rgba(255,230,80,.3),rgba(160,80,255,.35));background-size:300% 300%;box-shadow:inset 0 0 60px rgba(255,120,240,.6);z-index:2}body.fever #fever{opacity:1;animation:fv 1.2s linear infinite}@keyframes fv{to{background-position:300% 0}}
#chroma{position:absolute;inset:0;pointer-events:none;opacity:0;mix-blend-mode:screen;background:linear-gradient(90deg,rgba(255,0,90,.4),transparent 18%,transparent 82%,rgba(0,220,255,.4))}
#shieldTag{position:absolute;left:50%;top:52px;transform:translateX(-50%);padding:5px 12px;border-radius:12px;font-size:10px;font-weight:900;letter-spacing:2px;color:#7dffd9;background:rgba(10,40,40,.6);border:1px solid rgba(125,255,217,.5);box-shadow:0 0 14px rgba(125,255,217,.45);opacity:0;transition:opacity .3s;pointer-events:none;z-index:5}body.shield #shieldTag{opacity:1;animation:float 1.6s ease-in-out infinite}
#pops{position:absolute;inset:0;pointer-events:none}
.pop{position:absolute;transform:translate(-50%,-50%);font-weight:900;font-size:18px;letter-spacing:.5px;text-shadow:0 0 10px currentColor,0 2px 0 rgba(0,0,0,.5);animation:pop .9s cubic-bezier(.2,.8,.3,1) forwards;white-space:nowrap}
@keyframes pop{0%{opacity:0;transform:translate(-50%,-30%) scale(.4)}15%{opacity:1;transform:translate(-50%,-60%) scale(1.25)}100%{opacity:0;transform:translate(-50%,-260%) scale(.9)}}
#combo{position:absolute;left:50%;top:22%;transform:translateX(-50%);text-align:center;pointer-events:none;opacity:0;transition:opacity .25s}
